const std = @import("std");
const termscene = @import("termscene");
const core = @import("core.zig");

const ts_types = termscene.types;
const ts_scene = termscene.scene;
const ts_kitty = termscene.kitty;

pub const cell_cols: i32 = 2;
pub const cell_rows: i32 = 1;
pub const board_cols: i32 = core.board_w * cell_cols;
pub const board_rows: i32 = core.board_h * cell_rows;
pub const scene_cols: i32 = 42;
pub const scene_rows: i32 = 28;

const CellRect = struct {
    col: i32, row: i32, w: i32, h: i32,
    fn inset(self: CellRect, dx: i32, dy: i32) CellRect { return .{ .col = self.col + dx, .row = self.row + dy, .w = self.w - dx * 2, .h = self.h - dy * 2 }; }
};
const Layout = struct {
    title: CellRect, board: CellRect, board_panel: CellRect, next_panel: CellRect, hold_panel: CellRect, hud_panel: CellRect, instructions_panel: CellRect,
    fn init() Layout {
        const top_strip_h = 1;
        const board = CellRect{ .col = 4, .row = 3, .w = board_cols, .h = board_rows };
        const board_panel = CellRect{ .col = board.col - 1, .row = board.row - 1, .w = board.w + 2, .h = board.h + 2 };
        const side_col = board_panel.col + board_panel.w + 2;
        const next_panel = CellRect{ .col = side_col, .row = board_panel.row, .w = 12, .h = 6 };
        const hold_panel = CellRect{ .col = side_col, .row = next_panel.row + next_panel.h + 1, .w = 12, .h = 6 };
        const hud_panel = CellRect{ .col = side_col, .row = hold_panel.row + hold_panel.h + 1, .w = 12, .h = 5 };
        const instructions_panel = CellRect{ .col = board_panel.col, .row = board_panel.row + board_panel.h + 1, .w = scene_cols - board_panel.col + 1, .h = scene_rows - (board_panel.row + board_panel.h + 1) + 1 };
        return .{ .title = .{ .col = board_panel.col, .row = 1, .w = scene_cols - board_panel.col + 1, .h = top_strip_h }, .board = board, .board_panel = board_panel, .next_panel = next_panel, .hold_panel = hold_panel, .hud_panel = hud_panel, .instructions_panel = instructions_panel };
    }
};
const layout = Layout.init();
fn panelInner(panel: CellRect) CellRect { return panel.inset(1, 1); }
fn previewOrigin(piece: core.PieceKind, panel: CellRect) core.Point { const inner = panelInner(panel); const shape = core.Game.cells(piece, 0); var min_x: i32 = 99; var min_y: i32 = 99; var max_x: i32 = -99; var max_y: i32 = -99; for (shape) |cell| { min_x = @min(min_x, cell.x); min_y = @min(min_y, cell.y); max_x = @max(max_x, cell.x); max_y = @max(max_y, cell.y); } const piece_w_cols = (max_x - min_x + 1) * cell_cols; const piece_h_rows = max_y - min_y + 1; return .{ .x = inner.col + @divTrunc(inner.w - piece_w_cols, 2) - min_x * cell_cols, .y = inner.row + @divTrunc(inner.h - piece_h_rows, 2) - min_y }; }
const board_col: i32 = layout.board.col;
const board_row: i32 = layout.board.row;
const hud_row: i32 = layout.hud_panel.row + 1;
const bg_w: i32 = 840;
const bg_h: i32 = 560;
const tile_px: i32 = 32;
const row_strip_w: i32 = tile_px * 10;
const atlas_w: i32 = row_strip_w * 4;
const atlas_h: i32 = tile_px * 6;
const image_bg: u32 = 1001;
const image_atlas: u32 = 1002;
const placement_bg: u32 = 1;
const hud_text_namespace: u24 = 77;
const preview_sprite_namespace: u24 = 78;
const ghost_sprite_namespace: u24 = 79;
const active_sprite_namespace: u24 = 80;
const active_glow_sprite_namespace: u24 = 81;
const board_sprite_namespace: u24 = 82;
const board_glow_sprite_namespace: u24 = 83;
const sweep_sprite_namespace: u24 = 84;
const tint_sprite_namespace: u24 = 85;
const Rect = struct { x: i32, y: i32, w: i32, h: i32 };
const Color = struct { r: u8, g: u8, b: u8, a: u8 = 255 };
fn pieceColor(index: u8) Color { return switch (index) { 1 => .{ .r = 0, .g = 238, .b = 255 }, 2 => .{ .r = 255, .g = 220, .b = 90 }, 3 => .{ .r = 190, .g = 100, .b = 255 }, 4 => .{ .r = 120, .g = 255, .b = 130 }, 5 => .{ .r = 255, .g = 90, .b = 120 }, 6 => .{ .r = 100, .g = 170, .b = 255 }, 7 => .{ .r = 255, .g = 150, .b = 70 }, else => .{ .r = 0, .g = 0, .b = 0, .a = 0 } }; }
const Atlas = struct { block: [8]Rect, glow: [3]Rect, ghost: [2]Rect, sweep: [4]Rect, tint: Rect };

pub const Renderer = struct {
    allocator: std.mem.Allocator, atlas: Atlas, hud_engine: ts_scene.SceneEngine, hud_backend: ts_kitty.Backend,
    pub fn init(allocator: std.mem.Allocator, stdout_file: std.fs.File, writer: anytype) !Renderer {
        const bg = try allocator.alloc(u8, @as(usize, @intCast(bg_w * bg_h * 4))); defer allocator.free(bg);
        const atlas_buf = try allocator.alloc(u8, @as(usize, @intCast(atlas_w * atlas_h * 4))); defer allocator.free(atlas_buf);
        try ansiClear(writer); buildBackground(bg, bg_w, bg_h); const atlas = buildAtlas(atlas_buf, atlas_w, atlas_h); try kittyUpload(writer, image_bg, bg, bg_w, bg_h); try kittyUpload(writer, image_atlas, atlas_buf, atlas_w, atlas_h); try placeBackground(writer); try drawStaticHud(writer);
        return .{ .allocator = allocator, .atlas = atlas, .hud_engine = ts_scene.SceneEngine.init(allocator), .hud_backend = ts_kitty.Backend.init(allocator, stdout_file) };
    }
    pub fn deinit(self: *Renderer) void { self.hud_engine.deinit(); self.hud_backend.deinit(); }
    pub fn render(self: *Renderer, writer: anytype, game: *core.Game, t: f32) !void {
        _ = self.allocator;
        self.hud_engine.beginScene();
        try self.submitBoard(game); try self.submitGhost(game, t); try self.submitActive(game, t);
        const next_origin = previewOrigin(game.next, layout.next_panel); try self.submitPreview(game.next, next_origin.x, next_origin.y, false, 0);
        if (game.hold) |held| { const hold_origin = previewOrigin(held, layout.hold_panel); try self.submitPreview(held, hold_origin.x, hold_origin.y, game.hold_used, 100); }
        try self.submitSweep(game); try self.submitDangerTint(game, t); try self.hud_engine.diff(); try self.hud_backend.applySpriteOps(self.hud_engine.sprite_ops.items); try self.drawHud(writer, game, t);
    }
    fn submitSweep(self: *Renderer, game: *core.Game) !void { if (game.clear_fx_timer <= 0 or game.clear_fx_count == 0) return; const phase = 1.0 - (game.clear_fx_timer / 0.32); const frame: usize = @intCast(std.math.clamp(@as(i32, @intFromFloat(phase * 4.0)), 0, 3)); const src = self.atlas.sweep[frame]; const image: ts_types.ImageHandle = @enumFromInt(image_atlas); var i: usize = 0; while (i < game.clear_fx_count) : (i += 1) { const row = game.clear_fx_rows[i]; try self.hud_engine.sprite(.{ .key = ts_types.NodeKey.sprite(sweep_sprite_namespace, @as(u32, @intCast(i))), .image = image, .source_rect = .{ .x = src.x, .y = src.y, .w = src.w, .h = src.h }, .dest_rect = .{ .col = board_col, .row = board_row + row, .w = board_cols, .h = cell_rows }, .z = 20 }); } }
    fn submitDangerTint(self: *Renderer, game: *core.Game, t: f32) !void { var highest: i32 = core.board_h; var y: i32 = 0; while (y < core.board_h) : (y += 1) { var x: i32 = 0; while (x < core.board_w) : (x += 1) if (game.board[@intCast(y)][@intCast(x)] != 0) { highest = @min(highest, y); break; }; } if (highest > 4) return; const pulse = 0.35 + 0.35 * (0.5 + 0.5 * @sin(t * 6.0)); const tint_rect = if (pulse > 0.55) self.atlas.glow[2] else self.atlas.tint; try self.hud_engine.sprite(.{ .key = ts_types.NodeKey.sprite(tint_sprite_namespace, 0), .image = @enumFromInt(image_atlas), .source_rect = .{ .x = tint_rect.x, .y = tint_rect.y, .w = tint_rect.w, .h = tint_rect.h }, .dest_rect = .{ .col = board_col, .row = board_row, .w = board_cols, .h = board_rows }, .z = 15 }); }
    fn drawHud(self: *Renderer, writer: anytype, game: *core.Game, t: f32) !void { _ = writer; const hold_label_col = layout.hold_panel.col + 1; const hud_col = layout.hud_panel.col + 1; const info_col = layout.instructions_panel.col + 1; const info_width: usize = @intCast(layout.instructions_panel.w - 2); try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 10), .pos = .{ .col = layout.next_panel.col + 1, .row = layout.next_panel.row + 1 }, .content = "NEXT", .style = .{ .fg = .{ .r = 255, .g = 180, .b = 120 } } }); try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 11), .pos = .{ .col = layout.hold_panel.col + 1, .row = layout.hold_panel.row + 1 }, .content = "HOLD", .style = .{ .fg = .{ .r = 220, .g = 170, .b = 255 } } }); var buf_score: [32]u8 = undefined; var buf_lines: [32]u8 = undefined; var buf_level: [32]u8 = undefined; const score_text = try std.fmt.bufPrint(&buf_score, "SCR {d:<6}", .{game.score}); const lines_text = try std.fmt.bufPrint(&buf_lines, "LIN {d:<6}", .{game.lines}); const level_text = try std.fmt.bufPrint(&buf_level, "LVL {d:<6}", .{game.level}); try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 20), .pos = .{ .col = hud_col, .row = hud_row }, .content = score_text, .style = .{ .fg = .{ .r = 190, .g = 255, .b = 240 } } }); try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 21), .pos = .{ .col = hud_col, .row = hud_row + 1 }, .content = lines_text, .style = .{ .fg = .{ .r = 190, .g = 255, .b = 240 } } }); try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 22), .pos = .{ .col = hud_col, .row = hud_row + 2 }, .content = level_text, .style = .{ .fg = .{ .r = 190, .g = 255, .b = 240 } } }); const hold_status = if (game.hold_used) "HOLD SPENT" else if (game.paused) "PAUSED" else "HOLD READY"; const hold_color = if (game.hold_used) ts_types.Color{ .r = 255, .g = 170, .b = 220 } else if (game.paused) ts_types.Color{ .r = 255, .g = 220, .b = 120 } else ts_types.Color{ .r = 120, .g = 255, .b = 190 }; try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 30), .pos = .{ .col = hold_label_col, .row = layout.hold_panel.row + layout.hold_panel.h - 1 }, .content = hold_status, .style = .{ .fg = hold_color } }); const pulse = 0.5 + 0.5 * @sin(t * 5.0); const marquee = if (game.paused) "TTYTRIS  [PAUSED]  PRESS P TO RESUME  R TO RESET  Q TO QUIT" else "TTYTRIS  KITTY SPRITES + ALPHA OVERLAYS  FLASHY. PERSISTENT. NO FULL-FRAME BLITS."; const title_width = layout.title.w; const span = @max(@as(i32, @intCast(marquee.len)) - title_width, 0); const phase = 0.5 + 0.5 * @sin(t * 0.9); const offset: usize = @intCast(@min(span, @as(i32, @intFromFloat(phase * @as(f32, @floatFromInt(span)))))); const visible_width: usize = @intCast(title_width); const end2 = @min(offset + visible_width, marquee.len); var line_buf: [96]u8 = [_]u8{' '} ** 96; const slice = marquee[offset..end2]; @memcpy(line_buf[0..slice.len], slice); try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 40), .pos = .{ .col = layout.title.col, .row = layout.title.row }, .content = line_buf[0..visible_width], .style = .{ .fg = .{ .r = @intCast(100 + @as(i32, @intFromFloat(pulse * 80.0))), .g = @intCast(180 + @as(i32, @intFromFloat(pulse * 60.0))), .b = 255 } } }); if (game.show_help) { try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 50), .pos = .{ .col = info_col, .row = layout.instructions_panel.row + 2 }, .content = "MOVE: LEFT/RIGHT   ROT: UP/X CW", .style = .{ .fg = .{ .r = 200, .g = 220, .b = 255 } } }); try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 51), .pos = .{ .col = info_col, .row = layout.instructions_panel.row + 3 }, .content = "ROT CCW: Z   DROP: DOWN / SPACE", .style = .{ .fg = .{ .r = 200, .g = 220, .b = 255 } } }); try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 52), .pos = .{ .col = info_col, .row = layout.instructions_panel.row + 4 }, .content = "HOLD: C   PAUSE: P   RESET: R   QUIT: Q", .style = .{ .fg = .{ .r = 200, .g = 220, .b = 255 } } }); } const status_text = if (game.game_over) "GAME OVER — PRESS R TO RESTART" else if (game.paused) "PAUSED — PRESS P TO RESUME" else "STATUS OK — PRESS ? FOR HELP"; const status_style = if (game.game_over) ts_types.TextStyle{ .fg = .{ .r = 255, .g = 235, .b = 240 }, .bg = .{ .r = 90, .g = 20, .b = 40 } } else if (game.paused) ts_types.TextStyle{ .fg = .{ .r = 230, .g = 240, .b = 255 }, .bg = .{ .r = 30, .g = 40, .b = 90 } } else ts_types.TextStyle{ .fg = .{ .r = 160, .g = 210, .b = 255 }, .bg = null }; var status_buf: [96]u8 = [_]u8{' '} ** 96; const clipped = status_text[0..@min(status_text.len, info_width)]; @memcpy(status_buf[0..clipped.len], clipped); try self.hud_engine.text(.{ .key = ts_types.NodeKey.text(hud_text_namespace, 60), .pos = .{ .col = info_col, .row = layout.instructions_panel.row + 1 }, .content = status_buf[0..info_width], .style = status_style }); try self.hud_engine.diff(); try self.hud_backend.applyTextOps(self.hud_engine.text_ops.items); try self.hud_engine.commit(); }
    fn submitPreview(self: *Renderer, piece: core.PieceKind, col: i32, row: i32, dimmed: bool, id_base: u32) !void { const base = if (dimmed) self.atlas.ghost[0] else self.atlas.block[core.Game.kindIndex(piece)]; const shape = core.Game.cells(piece, 0); const image: ts_types.ImageHandle = @enumFromInt(image_atlas); for (shape, 0..) |cell, i| try self.hud_engine.sprite(.{ .key = ts_types.NodeKey.sprite(preview_sprite_namespace, id_base + @as(u32, @intCast(i))), .image = image, .source_rect = .{ .x = base.x, .y = base.y, .w = base.w, .h = base.h }, .dest_rect = .{ .col = col + cell.x * cell_cols, .row = row + cell.y, .w = cell_cols, .h = cell_rows }, .z = 8 }); }
    fn submitBoard(self: *Renderer, game: *core.Game) !void { const image: ts_types.ImageHandle = @enumFromInt(image_atlas); var y: i32 = 0; while (y < core.board_h) : (y += 1) { var x: i32 = 0; while (x < core.board_w) : (x += 1) { const cell = game.board[@intCast(y)][@intCast(x)]; if (cell != 0) { const base = self.atlas.block[cell]; const glow = self.atlas.glow[@intCast(@mod(x + y, 3))]; const id: u32 = @intCast(y * core.board_w + x); const dest: ts_types.CellRect = .{ .col = board_col + x * cell_cols, .row = board_row + y, .w = cell_cols, .h = cell_rows }; try self.hud_engine.sprite(.{ .key = ts_types.NodeKey.sprite(board_sprite_namespace, id), .image = image, .source_rect = .{ .x = base.x, .y = base.y, .w = base.w, .h = base.h }, .dest_rect = dest, .z = 5 }); try self.hud_engine.sprite(.{ .key = ts_types.NodeKey.sprite(board_glow_sprite_namespace, id), .image = image, .source_rect = .{ .x = glow.x, .y = glow.y, .w = glow.w, .h = glow.h }, .dest_rect = dest, .z = 6 }); } } } }
    fn submitGhost(self: *Renderer, game: *core.Game, t: f32) !void { const frame: usize = @intCast(@mod(@as(i32, @intFromFloat(t * 4.0)), 2)); const gy = game.ghostY(); const shape = core.Game.cells(game.current.kind, game.current.rot); const image: ts_types.ImageHandle = @enumFromInt(image_atlas); const src = self.atlas.ghost[frame]; for (shape, 0..) |cell, i| { const px = game.current.x + cell.x; const py = gy + cell.y; if (py < 0) continue; try self.hud_engine.sprite(.{ .key = ts_types.NodeKey.sprite(ghost_sprite_namespace, @as(u32, @intCast(i))), .image = image, .source_rect = .{ .x = src.x, .y = src.y, .w = src.w, .h = src.h }, .dest_rect = .{ .col = board_col + px * cell_cols, .row = board_row + py, .w = cell_cols, .h = cell_rows }, .z = 7 }); } }
    fn submitActive(self: *Renderer, game: *core.Game, t: f32) !void { const base = self.atlas.block[core.Game.kindIndex(game.current.kind)]; const glow_frame: usize = @intCast(@mod(@as(i32, @intFromFloat(t * 7.0)), 3)); const glow = self.atlas.glow[glow_frame]; const shape = core.Game.cells(game.current.kind, game.current.rot); const image: ts_types.ImageHandle = @enumFromInt(image_atlas); for (shape, 0..) |cell, i| { const px = game.current.x + cell.x; const py = game.current.y + cell.y; if (py < 0) continue; const dest: ts_types.CellRect = .{ .col = board_col + px * cell_cols, .row = board_row + py, .w = cell_cols, .h = cell_rows }; try self.hud_engine.sprite(.{ .key = ts_types.NodeKey.sprite(active_sprite_namespace, @as(u32, @intCast(i))), .image = image, .source_rect = .{ .x = base.x, .y = base.y, .w = base.w, .h = base.h }, .dest_rect = dest, .z = 8 }); try self.hud_engine.sprite(.{ .key = ts_types.NodeKey.sprite(active_glow_sprite_namespace, @as(u32, @intCast(i))), .image = image, .source_rect = .{ .x = glow.x, .y = glow.y, .w = glow.w, .h = glow.h }, .dest_rect = dest, .z = 9 }); } }
};

fn clearRgba(buf: []u8, color: Color) void { var i: usize = 0; while (i < buf.len) : (i += 4) { buf[i] = color.r; buf[i + 1] = color.g; buf[i + 2] = color.b; buf[i + 3] = color.a; } }
fn pixelIndex(w: i32, x: i32, y: i32) usize { return @as(usize, @intCast((y * w + x) * 4)); }
fn blendPixel(buf: []u8, w: i32, h: i32, x: i32, y: i32, color: Color) void { if (x < 0 or y < 0 or x >= w or y >= h or color.a == 0) return; const idx = pixelIndex(w, x, y); const src_a = @as(f32, @floatFromInt(color.a)) / 255.0; const dst_a = @as(f32, @floatFromInt(buf[idx + 3])) / 255.0; const out_a = src_a + dst_a * (1.0 - src_a); if (out_a <= 0) { buf[idx] = 0; buf[idx + 1] = 0; buf[idx + 2] = 0; buf[idx + 3] = 0; return; } const src_r = @as(f32, @floatFromInt(color.r)); const src_g = @as(f32, @floatFromInt(color.g)); const src_b = @as(f32, @floatFromInt(color.b)); const dst_r = @as(f32, @floatFromInt(buf[idx])); const dst_g = @as(f32, @floatFromInt(buf[idx + 1])); const dst_b = @as(f32, @floatFromInt(buf[idx + 2])); buf[idx] = @intFromFloat(std.math.clamp((src_r * src_a + dst_r * dst_a * (1.0 - src_a)) / out_a, 0, 255)); buf[idx + 1] = @intFromFloat(std.math.clamp((src_g * src_a + dst_g * dst_a * (1.0 - src_a)) / out_a, 0, 255)); buf[idx + 2] = @intFromFloat(std.math.clamp((src_b * src_a + dst_b * dst_a * (1.0 - src_a)) / out_a, 0, 255)); buf[idx + 3] = @intFromFloat(out_a * 255.0); }
fn fillRect(buf: []u8, w: i32, h: i32, x0: i32, y0: i32, rw: i32, rh: i32, color: Color) void { var y = y0; while (y < y0 + rh) : (y += 1) { var x = x0; while (x < x0 + rw) : (x += 1) blendPixel(buf, w, h, x, y, color); } }
fn strokeRect(buf: []u8, w: i32, h: i32, x0: i32, y0: i32, rw: i32, rh: i32, t: i32, color: Color) void { fillRect(buf, w, h, x0, y0, rw, t, color); fillRect(buf, w, h, x0, y0 + rh - t, rw, t, color); fillRect(buf, w, h, x0, y0, t, rh, color); fillRect(buf, w, h, x0 + rw - t, y0, t, rh, color); }
fn glowRect(buf: []u8, w: i32, h: i32, x0: i32, y0: i32, rw: i32, rh: i32, color: Color, radius: i32, strength: f32) void { var y = y0 - radius; while (y < y0 + rh + radius) : (y += 1) { var x = x0 - radius; while (x < x0 + rw + radius) : (x += 1) { var dx: f32 = 0; var dy: f32 = 0; if (x < x0) dx = @floatFromInt(x0 - x) else if (x >= x0 + rw) dx = @floatFromInt(x - (x0 + rw - 1)); if (y < y0) dy = @floatFromInt(y0 - y) else if (y >= y0 + rh) dy = @floatFromInt(y - (y0 + rh - 1)); const dist = @sqrt(dx * dx + dy * dy); if (dist <= @as(f32, @floatFromInt(radius))) { const a = (1.0 - dist / @as(f32, @floatFromInt(radius))) * strength; blendPixel(buf, w, h, x, y, .{ .r = color.r, .g = color.g, .b = color.b, .a = @intFromFloat(@as(f32, @floatFromInt(color.a)) * a) }); } } } }
fn drawPanel(buf: []u8, w: i32, h: i32, x: i32, y: i32, rw: i32, rh: i32, accent: Color) void { fillRect(buf, w, h, x, y, rw, rh, .{ .r = 10, .g = 16, .b = 30, .a = 230 }); glowRect(buf, w, h, x, y, rw, rh, accent, 18, 0.24); strokeRect(buf, w, h, x, y, rw, rh, 2, .{ .r = accent.r, .g = accent.g, .b = accent.b, .a = 180 }); }
fn chunkedApc(writer: anytype, prefix: []const u8, payload: []const u8) !void { const enc_len = std.base64.standard.Encoder.calcSize(payload.len); const b64 = try std.heap.page_allocator.alloc(u8, enc_len); defer std.heap.page_allocator.free(b64); _ = std.base64.standard.Encoder.encode(b64, payload); var offset: usize = 0; const chunk: usize = 3072; while (offset < b64.len) { const end = @min(offset + chunk, b64.len); const more: u8 = if (end < b64.len) '1' else '0'; if (offset == 0) { try writer.writeAll("\x1b_G"); try writer.writeAll(prefix); try writer.print(",m={c};", .{more}); try writer.writeAll(b64[offset..end]); try writer.writeAll("\x1b\\"); } else { try writer.print("\x1b_Gm={c};", .{more}); try writer.writeAll(b64[offset..end]); try writer.writeAll("\x1b\\"); } offset = end; } }
fn storeRaw(writer: anytype, image_id: u32, rgba: []const u8, w: i32, h: i32) !void { var prefix_buf: [128]u8 = undefined; const prefix = try std.fmt.bufPrint(&prefix_buf, "q=2,a=t,f=32,s={d},v={d},i={d}", .{ w, h, image_id }); try chunkedApc(writer, prefix, rgba); }
fn placeBackground(writer: anytype) !void { try moveCursor(writer, 1, 1); try writer.print("\x1b_Gq=2,a=p,C=1,i={d},p={d},c={d},r={d},z=-10;\x1b\\", .{ image_bg, placement_bg, scene_cols, scene_rows }); }
fn kittyUpload(writer: anytype, image_id: u32, rgba: []const u8, w: i32, h: i32) !void { try storeRaw(writer, image_id, rgba, w, h); }
fn moveCursor(writer: anytype, row: i32, col: i32) !void { try writer.print("\x1b[{d};{d}H", .{ row, col }); }
fn ansiClear(writer: anytype) !void { try writer.writeAll("\x1b[2J\x1b[H"); }
fn drawStaticHud(writer: anytype) !void { try moveCursor(writer, scene_rows, 1); try writer.writeAll("\x1b[0m"); }
fn buildBackground(buf: []u8, w: i32, h: i32) void { clearRgba(buf, .{ .r = 4, .g = 6, .b = 16, .a = 255 }); var y: i32 = 0; while (y < h) : (y += 1) { const wave = 0.5 + 0.5 * @sin(@as(f32, @floatFromInt(y)) * 0.03); fillRect(buf, w, h, 0, y, w, 1, .{ .r = @intFromFloat(5.0 + wave * 10.0), .g = @intFromFloat(8.0 + wave * 18.0), .b = @intFromFloat(20.0 + wave * 35.0), .a = 255 }); } var i: i32 = 0; while (i < 80) : (i += 1) fillRect(buf, w, h, @mod(i * 97, w - 4), @mod(i * 53, h - 4), 2, 2, .{ .r = 180, .g = 220, .b = 255, .a = 70 }); const cellw = @divTrunc(bg_w, scene_cols); const cellh = @divTrunc(bg_h, scene_rows); drawPanel(buf, w, h, (layout.board_panel.col - 1) * cellw, (layout.board_panel.row - 1) * cellh, layout.board_panel.w * cellw, layout.board_panel.h * cellh, .{ .r = 40, .g = 180, .b = 255, .a = 255 }); drawPanel(buf, w, h, (layout.next_panel.col - 1) * cellw, (layout.next_panel.row - 1) * cellh, layout.next_panel.w * cellw, layout.next_panel.h * cellh, .{ .r = 255, .g = 140, .b = 80, .a = 255 }); drawPanel(buf, w, h, (layout.hold_panel.col - 1) * cellw, (layout.hold_panel.row - 1) * cellh, layout.hold_panel.w * cellw, layout.hold_panel.h * cellh, .{ .r = 180, .g = 100, .b = 255, .a = 255 }); drawPanel(buf, w, h, (layout.hud_panel.col - 1) * cellw, (layout.hud_panel.row - 1) * cellh, layout.hud_panel.w * cellw, layout.hud_panel.h * cellh, .{ .r = 0, .g = 220, .b = 190, .a = 255 }); drawPanel(buf, w, h, (layout.instructions_panel.col - 1) * cellw, (layout.instructions_panel.row - 1) * cellh, layout.instructions_panel.w * cellw, layout.instructions_panel.h * cellh, .{ .r = 120, .g = 160, .b = 255, .a = 255 }); var gy: i32 = 0; while (gy < core.board_h) : (gy += 1) { var gx: i32 = 0; while (gx < core.board_w) : (gx += 1) fillRect(buf, w, h, (layout.board.col - 1) * cellw + gx * cell_cols * cellw, (layout.board.row - 1) * cellh + gy * cellh, cell_cols * cellw, cellh, if (@mod(gx + gy, 2) == 0) Color{ .r = 10, .g = 16, .b = 30, .a = 255 } else Color{ .r = 12, .g = 20, .b = 36, .a = 255 }); } }
fn buildAtlas(buf: []u8, w: i32, h: i32) Atlas { clearRgba(buf, .{ .r = 0, .g = 0, .b = 0, .a = 0 }); var atlas = Atlas{ .block = undefined, .glow = undefined, .ghost = undefined, .sweep = undefined, .tint = .{ .x = 8 * tile_px, .y = 2 * tile_px, .w = tile_px, .h = tile_px } }; atlas.block[0] = .{ .x = 0, .y = 0, .w = tile_px, .h = tile_px }; var i: u8 = 1; while (i <= 7) : (i += 1) { const idx = i - 1; const rect = Rect{ .x = @as(i32, idx) * tile_px, .y = 0, .w = tile_px, .h = tile_px }; atlas.block[i] = rect; drawBlockTile(buf, w, h, rect.x, rect.y, tile_px, pieceColor(i)); } atlas.ghost[0] = .{ .x = 0, .y = tile_px, .w = tile_px, .h = tile_px }; atlas.ghost[1] = .{ .x = tile_px, .y = tile_px, .w = tile_px, .h = tile_px }; drawGhostTile(buf, w, h, atlas.ghost[0].x, atlas.ghost[0].y, tile_px, 90); drawGhostTile(buf, w, h, atlas.ghost[1].x, atlas.ghost[1].y, tile_px, 130); atlas.glow[0] = .{ .x = 2 * tile_px, .y = tile_px, .w = tile_px, .h = tile_px }; atlas.glow[1] = .{ .x = 3 * tile_px, .y = tile_px, .w = tile_px, .h = tile_px }; atlas.glow[2] = .{ .x = 4 * tile_px, .y = tile_px, .w = tile_px, .h = tile_px }; drawGlowTile(buf, w, h, atlas.glow[0].x, atlas.glow[0].y, tile_px, .{ .r = 120, .g = 220, .b = 255, .a = 255 }, 60); drawGlowTile(buf, w, h, atlas.glow[1].x, atlas.glow[1].y, tile_px, .{ .r = 180, .g = 240, .b = 255, .a = 255 }, 90); drawGlowTile(buf, w, h, atlas.glow[2].x, atlas.glow[2].y, tile_px, .{ .r = 255, .g = 70, .b = 110, .a = 255 }, 70); var s: i32 = 0; while (s < 4) : (s += 1) { atlas.sweep[@intCast(s)] = .{ .x = s * row_strip_w, .y = 3 * tile_px, .w = row_strip_w, .h = tile_px }; drawSweepTile(buf, w, h, atlas.sweep[@intCast(s)].x, atlas.sweep[@intCast(s)].y, row_strip_w, tile_px, s); } fillRect(buf, w, h, atlas.tint.x, atlas.tint.y, atlas.tint.w, atlas.tint.h, .{ .r = 255, .g = 30, .b = 70, .a = 46 }); return atlas; }
fn drawBlockTile(buf: []u8, w: i32, h: i32, x: i32, y: i32, size: i32, color: Color) void { glowRect(buf, w, h, x + 2, y + 2, size - 4, size - 4, color, 8, 0.35); fillRect(buf, w, h, x + 3, y + 3, size - 6, size - 6, .{ .r = @intCast(@min(color.r / 2 + 30, 255)), .g = @intCast(@min(color.g / 2 + 30, 255)), .b = @intCast(@min(color.b / 2 + 30, 255)), .a = 255 }); fillRect(buf, w, h, x + 5, y + 5, size - 10, size - 10, color); fillRect(buf, w, h, x + 6, y + 6, size - 12, @divTrunc(size - 12, 3), .{ .r = 255, .g = 255, .b = 255, .a = 80 }); strokeRect(buf, w, h, x + 3, y + 3, size - 6, size - 6, 1, .{ .r = 255, .g = 255, .b = 255, .a = 90 }); }
fn drawGhostTile(buf: []u8, w: i32, h: i32, x: i32, y: i32, size: i32, alpha: u8) void { glowRect(buf, w, h, x + 4, y + 4, size - 8, size - 8, .{ .r = 120, .g = 220, .b = 255, .a = alpha }, 7, 0.25); fillRect(buf, w, h, x + 5, y + 5, size - 10, size - 10, .{ .r = 100, .g = 170, .b = 220, .a = alpha / 2 }); strokeRect(buf, w, h, x + 5, y + 5, size - 10, size - 10, 2, .{ .r = 220, .g = 250, .b = 255, .a = alpha }); }
fn drawGlowTile(buf: []u8, w: i32, h: i32, x: i32, y: i32, size: i32, color: Color, alpha: u8) void { var yy: i32 = 0; while (yy < size) : (yy += 1) { var xx: i32 = 0; while (xx < size) : (xx += 1) { const dx = @as(f32, @floatFromInt(xx - @divTrunc(size, 2))); const dy = @as(f32, @floatFromInt(yy - @divTrunc(size, 2))); const dist = @sqrt(dx * dx + dy * dy); const a = std.math.clamp(1.0 - dist / (@as(f32, @floatFromInt(size)) * 0.62), 0, 1); if (a > 0) blendPixel(buf, w, h, x + xx, y + yy, .{ .r = color.r, .g = color.g, .b = color.b, .a = @intFromFloat(@as(f32, @floatFromInt(alpha)) * a) }); } } }
fn drawSweepTile(buf: []u8, w: i32, h: i32, x: i32, y: i32, rw: i32, rh: i32, frame: i32) void { var xx: i32 = 0; while (xx < rw) : (xx += 1) { const nx = @as(f32, @floatFromInt(xx)) / @as(f32, @floatFromInt(rw)); const center = (@as(f32, @floatFromInt(frame)) + 0.6) / 4.6; const d = @abs(nx - center); const a = std.math.clamp(1.0 - d * 4.0, 0, 1); fillRect(buf, w, h, x + xx, y + 4, 1, rh - 8, .{ .r = 255, .g = 240, .b = 190, .a = @intFromFloat(190.0 * a) }); } }
